package com.opensocket.aievent.core.integration.identity;
import java.time.*; import java.util.*; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Profile;
@Profile("!prod") @ConditionalOnMissingBean(ProviderMetadataProbeGateway.class) @ConditionalOnProperty(prefix="integration-identity",name="metadata-probe",havingValue="METADATA_ONLY",matchIfMissing=true)
public class MetadataOnlyProviderMetadataProbeGateway implements ProviderMetadataProbeGateway {
 public ProviderMetadataSnapshot probe(IntegrationConnection c,IntegrationPrincipal p,IntegrationCredentialMetadata credential,IntegrationProjectMapping m,ProviderMetadataProbeRequest request){var now=OffsetDateTime.now();var fields=m.requiredFields().stream().map(v->new ProviderFieldMetadata(v,v,v,"STRING",true,List.of())).toList();return new ProviderMetadataSnapshot(request.tenantId(),"metadata-"+UUID.randomUUID(),c.connectionId(),m.mappingId(),m.externalProjectId(),m.externalProjectKey(),List.of(new ProviderProjectMetadata(m.externalProjectId(),m.externalProjectKey(),m.externalProjectKey(),true)),List.of(new ProviderIssueTypeMetadata(m.externalIssueType(),m.externalIssueType(),m.externalIssueType(),m.requiredFields())),fields,List.of(),List.of(),List.of(),List.of(),Map.of("METADATA_ONLY",PermissionProbeResultStatus.NOT_TESTED),null,null,ProjectMappingGovernanceService.schemaHash(m,fields),1,ProviderMetadataCacheStatus.FRESH,now,now.plusMinutes(15),"Metadata-only development snapshot. Provider validation has not been executed.",request.correlationId());}
}
